#[derive(Clone, Debug, PartialEq, Eq, uniffi::Enum)]
pub enum CommandOutcome {
    Announced,
    PacketDelivered {
        rtt_millis: u64,
        evidence: DeliveryEvidenceKind,
        packet_hash: Option<Vec<u8>>,
    },
    LinkCloseQueued,
    InterfaceAttached {
        interface: Vec<u8>,
    },
    InterfaceDetached {
        interface: Vec<u8>,
    },
    LinkEstablished {
        link_id: Vec<u8>,
        rtt_millis: u64,
    },
    PathDiscovered {
        hops: u8,
    },
    Identified,
    ResponseReceived {
        data: Vec<u8>,
        rtt_millis: u64,
    },
    ResponseSent {
        rtt_millis: u64,
    },
    ResourceSent,
    ResourceStrategySet,
    RequesterAllowed,
}
impl From<prns_host::CommandOutcome> for CommandOutcome {
    fn from(value: prns_host::CommandOutcome) -> Self {
        match value {
            prns_host::CommandOutcome::Announced => Self::Announced,
            prns_host::CommandOutcome::PacketDelivered {
                rtt_millis,
                evidence,
            } => {
                let packet_hash = match evidence {
                    prns_host::DeliveryEvidence::ExplicitProof(hash)
                    | prns_host::DeliveryEvidence::ImplicitProof(hash) => {
                        Some(hash.into_bytes().to_vec())
                    }
                    prns_host::DeliveryEvidence::Response => None,
                };
                Self::PacketDelivered {
                    rtt_millis,
                    evidence: evidence.kind().into(),
                    packet_hash,
                }
            }
            prns_host::CommandOutcome::LinkCloseQueued => Self::LinkCloseQueued,
            prns_host::CommandOutcome::InterfaceAttached { interface } => Self::InterfaceAttached {
                interface: interface.into_bytes().to_vec(),
            },
            prns_host::CommandOutcome::InterfaceDetached { interface } => Self::InterfaceDetached {
                interface: interface.into_bytes().to_vec(),
            },
            prns_host::CommandOutcome::LinkEstablished {
                link_id,
                rtt_millis,
            } => Self::LinkEstablished {
                link_id: link_id.into_bytes().to_vec(),
                rtt_millis,
            },
            prns_host::CommandOutcome::PathDiscovered { hops } => Self::PathDiscovered { hops },
            prns_host::CommandOutcome::Identified => Self::Identified,
            prns_host::CommandOutcome::ResponseReceived { data, rtt_millis } => {
                Self::ResponseReceived { data, rtt_millis }
            }
            prns_host::CommandOutcome::ResponseSent { rtt_millis } => {
                Self::ResponseSent { rtt_millis }
            }
            prns_host::CommandOutcome::ResourceSent => Self::ResourceSent,
            prns_host::CommandOutcome::ResourceStrategySet => Self::ResourceStrategySet,
            prns_host::CommandOutcome::RequesterAllowed => Self::RequesterAllowed,
        }
    }
}
impl TryFrom<CommandOutcome> for prns_host::CommandOutcome {
    type Error = BindingError;
    fn try_from(value: CommandOutcome) -> Result<Self, Self::Error> {
        Ok(match value {
            CommandOutcome::Announced => Self::Announced,
            CommandOutcome::PacketDelivered {
                rtt_millis,
                evidence,
                packet_hash,
            } => {
                let evidence = match (evidence, packet_hash) {
                    (DeliveryEvidenceKind::ExplicitProof, Some(hash)) => {
                        prns_host::DeliveryEvidence::ExplicitProof(prns_host::PacketHash::new(
                            fixed_bytes(hash, "PacketHash")?,
                        ))
                    }
                    (DeliveryEvidenceKind::ImplicitProof, Some(hash)) => {
                        prns_host::DeliveryEvidence::ImplicitProof(prns_host::PacketHash::new(
                            fixed_bytes(hash, "PacketHash")?,
                        ))
                    }
                    (DeliveryEvidenceKind::Response, None) => prns_host::DeliveryEvidence::Response,
                    _ => {
                        return Err(invalid(
                            "PacketDelivered",
                            "proof evidence requires a packet hash; response evidence forbids one",
                        ))
                    }
                };
                Self::PacketDelivered {
                    rtt_millis: safe_uint(rtt_millis)?,
                    evidence,
                }
            }
            CommandOutcome::LinkCloseQueued => Self::LinkCloseQueued,
            CommandOutcome::InterfaceAttached { interface } => Self::InterfaceAttached {
                interface: prns_host::InterfaceId::new(fixed_bytes::<8>(interface, "InterfaceId")?),
            },
            CommandOutcome::InterfaceDetached { interface } => Self::InterfaceDetached {
                interface: prns_host::InterfaceId::new(fixed_bytes::<8>(interface, "InterfaceId")?),
            },
            CommandOutcome::LinkEstablished {
                link_id,
                rtt_millis,
            } => Self::LinkEstablished {
                link_id: prns_host::LinkId::new(fixed_bytes::<16>(link_id, "LinkId")?),
                rtt_millis: safe_uint(rtt_millis)?,
            },
            CommandOutcome::PathDiscovered { hops } => Self::PathDiscovered { hops },
            CommandOutcome::Identified => Self::Identified,
            CommandOutcome::ResponseReceived { data, rtt_millis } => Self::ResponseReceived {
                data,
                rtt_millis: safe_uint(rtt_millis)?,
            },
            CommandOutcome::ResponseSent { rtt_millis } => Self::ResponseSent {
                rtt_millis: safe_uint(rtt_millis)?,
            },
            CommandOutcome::ResourceSent => Self::ResourceSent,
            CommandOutcome::ResourceStrategySet => Self::ResourceStrategySet,
            CommandOutcome::RequesterAllowed => Self::RequesterAllowed,
        })
    }
}
