#[derive(Clone, Debug, PartialEq, Eq, uniffi::Enum)]
pub enum HostFailure {
    EventBackpressureExceeded {
        limits: PrnsLimits,
        rejected_event_bytes: u64,
    },
    BackendFailed {
        component: String,
        detail: String,
    },
    ContractViolated {
        detail: String,
    },
}
impl From<prns_host::HostFailure> for HostFailure {
    fn from(value: prns_host::HostFailure) -> Self {
        match value {
            prns_host::HostFailure::EventBackpressureExceeded {
                limits,
                rejected_event_bytes,
            } => Self::EventBackpressureExceeded {
                limits: limits.into(),
                rejected_event_bytes: rejected_event_bytes as u64,
            },
            prns_host::HostFailure::BackendFailed { component, detail } => {
                Self::BackendFailed { component, detail }
            }
            prns_host::HostFailure::ContractViolated { detail } => {
                Self::ContractViolated { detail }
            }
        }
    }
}
impl TryFrom<HostFailure> for prns_host::HostFailure {
    type Error = BindingError;
    fn try_from(value: HostFailure) -> Result<Self, Self::Error> {
        Ok(match value {
            HostFailure::EventBackpressureExceeded {
                limits,
                rejected_event_bytes,
            } => Self::EventBackpressureExceeded {
                limits: limits.try_into()?,
                rejected_event_bytes: usize::try_from(safe_uint(rejected_event_bytes)?)
                    .map_err(|_| invalid("rejectedEventBytes", "outside native size range"))?,
            },
            HostFailure::BackendFailed { component, detail } => {
                Self::BackendFailed { component, detail }
            }
            HostFailure::ContractViolated { detail } => Self::ContractViolated { detail },
        })
    }
}
#[derive(Clone, Debug, PartialEq, Eq, uniffi::Enum)]
pub enum HostLifecycleState {
    Starting,
    Running,
    Stopping,
    Stopped { reason: StopReason },
    Failed { failure: HostFailure },
}
impl From<prns_host::LifecycleState> for HostLifecycleState {
    fn from(value: prns_host::LifecycleState) -> Self {
        match value {
            prns_host::LifecycleState::Starting => Self::Starting,
            prns_host::LifecycleState::Running => Self::Running,
            prns_host::LifecycleState::Stopping => Self::Stopping,
            prns_host::LifecycleState::Stopped(reason) => Self::Stopped {
                reason: reason.into(),
            },
            prns_host::LifecycleState::Failed(failure) => Self::Failed {
                failure: failure.into(),
            },
        }
    }
}
impl TryFrom<HostLifecycleState> for prns_host::LifecycleState {
    type Error = BindingError;
    fn try_from(value: HostLifecycleState) -> Result<Self, Self::Error> {
        Ok(match value {
            HostLifecycleState::Starting => Self::Starting,
            HostLifecycleState::Running => Self::Running,
            HostLifecycleState::Stopping => Self::Stopping,
            HostLifecycleState::Stopped { reason } => Self::Stopped(reason.into()),
            HostLifecycleState::Failed { failure } => Self::Failed(failure.try_into()?),
        })
    }
}
#[derive(Clone, Debug, PartialEq, Eq, uniffi::Enum)]
pub enum CommandSettlement {
    Succeeded { outcome: CommandOutcome },
    Failed { failure: CommandFailure },
}
impl From<Result<prns_host::CommandOutcome, prns_host::CommandFailure>> for CommandSettlement {
    fn from(value: Result<prns_host::CommandOutcome, prns_host::CommandFailure>) -> Self {
        match value {
            Ok(value) => Self::Succeeded {
                outcome: value.into(),
            },
            Err(value) => Self::Failed {
                failure: value.into(),
            },
        }
    }
}
impl DiagnosticEvent {
    pub fn dropped(count: u128) -> Self {
        Self::DiagnosticsDropped {
            count: count.into(),
        }
    }
}
pub fn diagnostic_batch(value: prns_host::DiagnosticBatch) -> Vec<DiagnosticEvent> {
    let mut events: Vec<_> = value.events.into_iter().map(Into::into).collect();
    if value.dropped_newest != 0 {
        events.push(DiagnosticEvent::dropped(value.dropped_newest));
    }
    events
}
